import { Card, Form, Radio, Result, Steps, Textarea, Typography } from '@chameleon-ui/components'
import type { StepItem } from '@chameleon-ui/components'
import { useState, type FormEvent } from 'react'
import { createBlockCopy } from '../copy.js'
import { approvalFlowLocaleTrees } from './locale-map.js'
import './styles.css'

export type ApprovalDecision = 'approve' | 'reject'
export type ApprovalStatus = 'pending' | 'approved' | 'rejected'

export interface ApprovalFlowProps {
  locale?: string
  status?: ApprovalStatus
  onDecide?: (payload: { decision: ApprovalDecision; comment: string }) => void
  className?: string
}

export function ApprovalFlow({
  locale = 'en',
  status: initialStatus = 'pending',
  onDecide,
  className,
}: ApprovalFlowProps) {
  const { t } = createBlockCopy(approvalFlowLocaleTrees, locale)
  const [status, setStatus] = useState<ApprovalStatus>(initialStatus)
  const [decision, setDecision] = useState<ApprovalDecision | ''>('')
  const [comment, setComment] = useState('')
  const [error, setError] = useState<string | null>(null)
  const classes = ['cu-block-approval-flow', className].filter(Boolean).join(' ')
  const currentValue = status === 'pending' ? 'review' : 'done'
  const openCount = status === 'pending' ? 1 : 0

  const items: StepItem[] = [
    { value: 'submit', label: t('approval.stepSubmit'), description: t('approval.stepSubmitHint') },
    { value: 'review', label: t('approval.stepReview'), description: t('approval.stepReviewHint') },
    { value: 'done', label: t('approval.stepDone'), description: t('approval.stepDoneHint') },
  ]

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    if (!decision || !comment.trim()) {
      setError(t('approval.errorRequired'))
      return
    }
    setError(null)
    const next = decision === 'approve' ? 'approved' : 'rejected'
    setStatus(next)
    onDecide?.({ decision, comment: comment.trim() })
  }

  return (
    <section
      className={classes}
      data-ai-role="approval-flow"
      data-ai-intent="review-request"
      data-ai-state={status}
    >
      <Typography variant="heading-1">{t('approval.title')}</Typography>
      <Typography variant="body">{t('approval.subtitle')}</Typography>
      <p className="cu-block-approval-flow__meta">{t('approval.requestCount', { count: openCount })}</p>
      <Steps currentValue={currentValue} items={items} label={t('approval.stepsLabel')} />
      <Card className="cu-block-approval-flow__panel" padding="lg" variant="outlined">
        <Typography variant="heading-2">{t('approval.subject')}</Typography>
        {status === 'pending' ? (
          <>
            {error ? (
              <p className="cu-block-approval-flow__error" role="alert">
                {error}
              </p>
            ) : null}
            <Form onSubmit={handleSubmit} submitLabel={t('approval.submit')}>
              <Radio
                label={t('approval.decisionLabel')}
                name="approval-decision"
                onChange={(value) => setDecision(value as ApprovalDecision)}
                options={[
                  { value: 'approve', label: t('approval.approve') },
                  { value: 'reject', label: t('approval.reject') },
                ]}
                value={decision}
              />
              <Textarea label={t('approval.commentLabel')} onChange={setComment} value={comment} />
            </Form>
          </>
        ) : (
          <Result
            description={status === 'approved' ? t('approval.successBody') : t('approval.rejectedBody')}
            status={status === 'approved' ? 'success' : 'error'}
            title={status === 'approved' ? t('approval.successTitle') : t('approval.rejectedTitle')}
          />
        )}
      </Card>
    </section>
  )
}

{
  "schemaVersion": "0.2",
  "slug": "approval-flow",
  "name": "Approval flow",
  "status": "experimental",
  "purpose": "Walk a request through submit, review, and a recorded approve or reject decision.",
  "scenarios": [
    "Review an open request against a three-step tracker",
    "Approve or reject with a required comment",
    "Show a success or error result after the decision"
  ],
  "props": {
    "locale": {
      "type": "string",
      "required": false,
      "description": "BCP 47 locale for bundled block copy.",
      "default": "en"
    },
    "status": {
      "type": "string",
      "required": false,
      "description": "Initial request status: pending, approved, or rejected.",
      "default": "pending"
    },
    "onDecide": {
      "type": "event",
      "required": false,
      "description": "Called with the decision and comment after client validation."
    }
  },
  "variants": [
    {
      "name": "density",
      "values": ["comfortable", "compact"],
      "default": "comfortable",
      "description": "Inherits density from token rungs rather than a local viewport query."
    }
  ],
  "states": [
    { "name": "pending", "description": "Decision form is visible." },
    { "name": "approved", "description": "Success result is visible." },
    { "name": "rejected", "description": "Error result is visible." }
  ],
  "composition": {
    "allowedParents": ["page", "dialog", "card"],
    "allowedChildren": ["steps", "form", "result", "radio", "textarea", "card", "typography"],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not skip the comment field when recording a decision.",
    "Do not claim 21 authored languages; 19 locales are ICU skeletons."
  ],
  "a11y": {
    "role": "region",
    "keyboard": ["Tab reaches decision radios, comment, and submit", "Enter submits the decision form"],
    "focus": "Fields and actions remain in document order with a visible focus ring.",
    "labeling": "Steps, decision radios, comment, and submit have accessible names.",
    "wcag": ["2.1.1", "2.4.7", "3.3.2", "4.1.2"]
  },
  "responsive": {
    "strategy": "Single-column card; steps adapt with their own @container queries. No viewport media queries.",
    "breakpoints": {
      "compact": "Steps stack; form uses full inline size with 44px targets.",
      "medium": "Steps sit in a row when the stepper container allows.",
      "large": "Steps sit in a row when the stepper container allows."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction comes from locale language, never a hardcoded ltr attribute.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "approval-flow",
    "states": ["pending", "approved", "rejected"],
    "intents": ["review-request"]
  }
}

{
  "slug": "approval-flow",
  "type": "registry:block",
  "name": "Approval flow",
  "dependencies": ["card", "form", "radio", "result", "steps", "textarea", "typography"],
  "theme": { "constraints": [] },
  "rtl": true,
  "platforms": {
    "compact": true,
    "medium": true,
    "large": true
  },
  "preview": {
    "width": 768,
    "title": "Review, approve, or reject a request"
  }
}

.cu-block-approval-flow {
  display: grid;
  gap: var(--cu-space-3);
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
}

.cu-block-approval-flow__meta,
.cu-block-approval-flow__error {
  margin-block: 0;
  color: var(--cu-color-fg-default);
  font-size: var(--cu-typography-size-caption);
}

.cu-block-approval-flow__error {
  color: var(--cu-color-palette-brand);
}

.cu-block-approval-flow__panel {
  display: grid;
  gap: var(--cu-space-3);
}
